def compare(game, guess):
    """Determine if a person correctly guessed the results of matches.
    You are given two arrays of scores and guesses of equal length. 
    Return an array denoting how far off each guess was. If guessed correctly, the value is 0; otherwise, it's the absolute difference between the guess and the score.

    example:
    compare([1,2,3,4,5,1],[1,2,3,4,2,-2]) -> [0,0,0,0,3,3]
    compare([0,5,0,0,0,4],[4,1,1,0,0,-2]) -> [4,4,1,0,0,6]
    """
    results = []
    for i in range(len(game)):
        if game[i] == guess[i]:
            results.append(0)
        else:
            results.append(abs(game[i] - guess[i]))
    return results
